"""Build all textual evaluation claims and the curve from results.json."""
import json
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

r=json.loads(Path('results.json').read_text())
def pct(x): return 'n/a' if x is None else f'{100*x:.2f}%'
def metric(m,k):
    ci=m.get('ci95',{}).get(k)
    return pct(m[k]) + (f' [{pct(ci[0])}, {pct(ci[1])}]' if ci else '')
lines=['<!-- Generated by scripts/report.py from results.json. -->', '## Held-out evaluation', '',f"Seed A: {r['protocol']['train_seed']}; held-out B: {r['protocol']['held_out_seed']}. {r['dataset']['factories']:,} factories × 12 months. Selected ratio threshold: {r['protocol']['threshold']}. Minimum balanced error on A, with conservative tie-breaking; no target score. Labels never enter detection SQL.", '', '| Unit | TP | FP | FN | TN | Recall [95% CI] | FPR [95% CI] |','|---|---:|---:|---:|---:|---|---|']
for level in ['factory_month','factory']:
    m=r[level];lines.append(f"| {level} | {m['tp']} | {m['fp']} | {m['fn']} | {m['tn']} | {metric(m,'recall')} | {metric(m,'fpr')} |")
lines += ['', 'Factory-month negatives include inactive months of cheat factories. Factory scores use any flagged month. Intervals use 1,000 factory-cluster bootstrap resamples, conditional on the selected threshold; they do not quantify generator bias.', '', '### Recall by type and intensity', '', '| Type / intensity | Factory-month recall [95% CI] | Factory recall [95% CI] |', '|---|---|---|']
for key,m in r['recall_by_type_intensity']['factory_month'].items():
    lines.append(f"| {key} | {metric(m,'recall')} | {metric(r['recall_by_type_intensity']['factory'][key],'recall')} |")
lines+=['','### Honest decoy false positives','','| Decoy | Factory-month FPR [95% CI] | Factory FPR [95% CI] |','|---|---|---|']
for key,m in r['fpr_by_decoy']['factory_month'].items():
    lines.append(f"| {key} | {metric(m,'fpr')} | {metric(r['fpr_by_decoy']['factory'][key],'fpr')} |")
lines+=['',f"{r['single_signal_decoy_months']:,} honest decoy months triggered exactly one source family and were not prioritised. Review-only means excluded from the priority queue, not legally cleared.", '', '### Review queue precision', '', '| k | Mean precision [95% CI] |', '|---:|---|']
for k,m in r['precision_at_k'].items():
    lines.append(f"| {k} | {pct(m['macro_precision'])} [{pct(m['ci95'][0])}, {pct(m['ci95'][1])}] |")
lines+=['','Monthly snapshots approximate a weekly workload; there is no weekly-resolution dataset. Each returns up to k flagged factories, with no padding. Empty months are excluded. Queue intervals use 200 factory-cluster resamples and recompute the ranks. Per-month returned counts are in results.json.', '', '### Discrepancy classification', '', 'Rows are truth; columns are predicted. Strongest non-financial signal determines the case class, including review-only cases. Clean months are excluded. `no signal` records abstention. These classes describe evidence, not guilt.', '', '| Truth | '+' | '.join(r['confusion']['columns_predicted'])+' |', '|---|'+'---:|'*6]
for label,values in zip(r['confusion']['rows_truth'],r['confusion']['counts']):
    lines.append('| '+label+' | '+' | '.join(map(str,values))+' |')
lines+=['','### Misses and limits','',f"Missed {r['misses']['factory_months']:,} active cheat months; {r['misses']['factories_never_caught']:,} cheat factories were never caught. Full rows and reasons: [misses.csv](reports/misses.csv). Evasive factory-month recall: {metric(r['evasive']['factory_month'],'recall')}.",'', '| Factory | Month | Scenario | Intensity | Signals | Reason |','|---|---|---|---:|---:|---|']
for m in r['misses']['examples'][:5]:
    lines.append(f"| {m['factory_id']} | {m['period_month']} | {m['scenario']} | {pct(m['intensity'])} | {m['signals']} | {m['reason']} |")
lines+=['','![Held-out recall vs false-positive rate](reports/recall_fpr.png)','','The curve is diagnostic on B and was not used to select the threshold. A and B share one generator: results measure synthetic scenario recovery only. Independent source groups can still be correlated in reality. Supplier ownership and one primary supplier per factory are simplifying assumptions. The fixed yield/power model intentionally struggles with legitimate operating changes. Zero observed false positives would not prove zero real-world risk.']
text='\n'.join(lines)+'\n'
Path('reports/evaluation.md').write_text(text)
readme=Path('README.md').read_text()
if '<!-- EVALUATION START -->' in readme:
    start,end=readme.split('<!-- EVALUATION START -->',1)
    _,tail=end.split('<!-- EVALUATION END -->',1)
    Path('README.md').write_text(start+'<!-- EVALUATION START -->\n'+text+'<!-- EVALUATION END -->'+tail)
curve=r['threshold_curve']
fig,ax=plt.subplots(figsize=(7.5,4.5))
ax.plot([x['fpr']*100 for x in curve],[x['recall']*100 for x in curve],'o-',color='#156b68')
chosen=next(x for x in curve if x['threshold']==r['protocol']['threshold'])
ax.scatter([chosen['fpr']*100],[chosen['recall']*100],s=100,color='#bd4b30',label=f"A-selected threshold {chosen['threshold']}",zorder=3)
ax.set(xlabel='Held-out factory-month false-positive rate (%)',ylabel='Held-out recall (%)',title='Threshold sensitivity on seed B (not used for tuning)')
ax.grid(alpha=.2);ax.legend();fig.tight_layout();fig.savefig('reports/recall_fpr.png',dpi=160);plt.close(fig)
summary={'factory_month_recall':pct(r['factory_month']['recall']),'factory_month_fpr':pct(r['factory_month']['fpr']),'factory_recall':pct(r['factory']['recall']),'factory_fpr':pct(r['factory']['fpr']),'misses':r['misses']['factory_months'],'factories':r['dataset']['factories'],'raw_evidence_rows':r['dataset']['raw_evidence_rows'],'single_signal_decoys':r['single_signal_decoy_months']}
Path('reports/presentation_metrics.json').write_text(json.dumps(summary,indent=2)+'\n')
